include 'includes/session.php';include 'includes/functions.php';if(empty($_SESSION['userId'])){header('Location: login.php');exit;}$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT p.*,m.FullName,m.Phone,b.name bank_name,u.FullName cashier,c.remarks FROM payments p JOIN members m ON m.id=p.member_id JOIN banks b ON b.id=p.bank_id LEFT JOIN users u ON u.id=p.user_id JOIN charges c ON c.id=p.charge_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Receipt not found.');}
